    assertTrue(gmsJoinLeave.isCoordinator());
    // wait for suspect processing
    Thread.sleep(10000);
    verify(healthMonitor, atLeast(1)).checkIfAvailable(isA(DistributedMember.class), isA(String.class), isA(Boolean.class));
