            // when the waitUnitFlushed() called the 2nd time, queue.size() will return 0
            return 0;
        }
    });
    index.waitUntilFlushed(MAX_WAIT, TimeUnit.MILLISECONDS);
    verify(cache).getAsyncEventQueue(eq(expectedIndexName));
}

